{
  "jsonrpc": "2.0",
  "id": "batch-process-001",
  "method": "tools/batch_call",
  "params": {
    "tools": [
      {
        "id": "task-A",
        "name": "image_processing",
        "arguments": {"operation": "enhance", "image_url": "..."}
      },
      {
        "id": "task-B",
        "name": "text_analysis",
        "arguments": {"text": "...", "analysis_type": "sentiment"}
      },
      {
        "id": "task-C",
        "name": "data_query",
        "arguments": {"query": "SELECT * FROM users WHERE active=1"}
      }
    ]
  }
}
