{
  "jsonrpc": "2.0",
  "method": "tools/progress",
  "params": {
    "batch_id": "batch-process-001",
    "completed": ["task-B"],
    "in_progress": ["task-A", "task-C"],
    "progress": {"task-A": 0.6, "task-C": 0.3}
  }
}
